  "inlineSchema": "// Planning Poker - Data Model\n// https://pris.ly/d/prisma-schema\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// Session: Main container for a planning poker session\nmodel Session {\n  id             String        @id @default(cuid())\n  slug           String        @unique @db.VarChar(255) // Unique URL-friendly identifier\n  name           String        @db.VarChar(255)\n  description    String?       @db.Text\n  status         SessionStatus @default(ACTIVE) // ACTIVE, CLOSED, ARCHIVED\n  moderatorId    String        @db.VarChar(255) // Pseudonym of moderator\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  lastActivityAt DateTime      @default(now()) // Updated on any participant activity\n  expiresAt      DateTime? // Set when session becomes archived\n\n  // Relations\n  participants Participant[]\n  epics        Epic[]\n  stories      Story[]\n  tasks        Task[]\n  votes        Vote[]\n  messages     Message[]\n\n  // Indexes for efficient queries\n  @@index([slug])\n  @@index([lastActivityAt])\n  @@index([createdAt])\n  @@index([status])\n}\n\n// Participant: Individual in a session\nmodel Participant {\n  id             String   @id @default(cuid())\n  sessionId      String\n  pseudonym      String   @db.VarChar(50)\n  joinedAt       DateTime @default(now())\n  lastActivityAt DateTime @default(now())\n\n  // Relations\n  session  Session   @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  votes    Vote[]\n  messages Message[]\n\n  // Constraints\n  @@unique([sessionId, pseudonym]) // No duplicate names within session\n  @@index([sessionId])\n}\n\n// Epic: Top-level organizational unit\nmodel Epic {\n  id             String   @id @default(cuid())\n  sessionId      String\n  title          String   @db.VarChar(255)\n  description    String?  @db.Text\n  estimatePoints Int? // Final consensus estimate\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // Relations\n  session Session @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  stories Story[]\n\n  // Indexes\n  @@index([sessionId])\n  @@index([createdAt])\n}\n\n// Story: User story within an epic\nmodel Story {\n  id             String   @id @default(cuid())\n  sessionId      String\n  epicId         String\n  title          String   @db.VarChar(255)\n  description    String?  @db.Text\n  estimatePoints Int? // Final consensus estimate\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // Relations\n  session Session @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  epic    Epic    @relation(fields: [epicId], references: [id], onDelete: Cascade)\n  tasks   Task[]\n\n  // Indexes\n  @@index([sessionId])\n  @@index([epicId])\n  @@index([createdAt])\n}\n\n// Task: Atomic unit of work within a story\nmodel Task {\n  id              String     @id @default(cuid())\n  sessionId       String\n  storyId         String\n  title           String     @db.VarChar(255)\n  description     String?    @db.Text\n  estimatePoints  Int? // Final consensus estimate\n  status          TaskStatus @default(UNESTIMATED) // UNESTIMATED, VOTING, REVEALED, ESTIMATED\n  revealedAverage Float? // Average of votes when revealed\n  revealedMedian  Float? // Median of votes when revealed\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  // Relations\n  session Session @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  story   Story   @relation(fields: [storyId], references: [id], onDelete: Cascade)\n  votes   Vote[]\n\n  // Indexes\n  @@index([sessionId])\n  @@index([storyId])\n  @@index([status])\n  @@index([createdAt])\n}\n\n// Vote: Individual participant vote on a task\nmodel Vote {\n  id            String   @id @default(cuid())\n  taskId        String\n  participantId String\n  sessionId     String\n  card          String   @db.VarChar(10) // \"1\", \"2\", \"3\", \"5\", \"8\", \"13\", \"21\", \"?\", \"coffee\"\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Relations\n  task        Task        @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  participant Participant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n  session     Session     @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  // Constraints: Each participant votes only once per task\n  @@unique([taskId, participantId])\n  @@index([sessionId])\n  @@index([taskId])\n  @@index([participantId])\n  @@index([createdAt])\n}\n\n// Message: Chat message in a session\nmodel Message {\n  id            String   @id @default(cuid())\n  sessionId     String\n  participantId String\n  content       String   @db.VarChar(500) // Truncated to 500 chars\n  createdAt     DateTime @default(now())\n\n  // Relations\n  session     Session     @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  participant Participant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n\n  // Indexes\n  @@index([sessionId])\n  @@index([participantId])\n  @@index([createdAt])\n}\n\n// Enums\nenum SessionStatus {\n  ACTIVE\n  CLOSED\n  ARCHIVED\n}\n\nenum TaskStatus {\n  UNESTIMATED\n  VOTING\n  REVEALED\n  ESTIMATED\n}\n",
